-- C11 / P11.3 — subtype-specific book production QA with immutable evidence and fail-closed advancement.
create table if not exists public.command_center_book_qa_profile_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 profile_event_id text not null check(btrim(profile_event_id)<>''), profile_key text not null check(btrim(profile_key)<>''), subtype text not null check(subtype in ('fiction','nonfiction','cookbook','workbook','coloring','activity')), version integer not null check(version>0), source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,profile_event_id), unique(owner_id,profile_key,version)
);
create table if not exists public.command_center_book_qa_profile_gate_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 gate_event_id text not null check(btrim(gate_event_id)<>''), profile_key text not null check(btrim(profile_key)<>''), profile_version integer not null check(profile_version>0), requirement_key text not null check(btrim(requirement_key)<>''), gate_kind text not null check(gate_kind in ('editing','continuity','originality','image','interior','format')), required boolean not null, description text not null check(btrim(description)<>''), observed_at timestamptz not null,
 primary key(owner_id,gate_event_id), unique(owner_id,profile_key,profile_version,requirement_key)
);
create table if not exists public.command_center_book_qa_evidence_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 evidence_event_id text not null check(btrim(evidence_event_id)<>''), evidence_id text not null check(btrim(evidence_id)<>''), project_id text not null check(btrim(project_id)<>''), book_id text not null check(btrim(book_id)<>''), profile_key text not null check(btrim(profile_key)<>''), profile_version integer not null check(profile_version>0), requirement_key text not null check(btrim(requirement_key)<>''), passed boolean not null, evidence_refs text[] not null check(cardinality(evidence_refs)>0), artifact_refs text[] not null check(cardinality(artifact_refs)>0), evaluator_ref text not null check(btrim(evaluator_ref)<>''), observed_at timestamptz not null,
 primary key(owner_id,evidence_event_id), unique(owner_id,evidence_id)
);
create table if not exists public.command_center_book_qa_assessment_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 assessment_event_id text not null check(btrim(assessment_event_id)<>''), project_id text not null check(btrim(project_id)<>''), book_id text not null check(btrim(book_id)<>''), profile_key text not null check(btrim(profile_key)<>''), profile_version integer not null check(profile_version>0), pass boolean not null, may_advance boolean not null, missing text[] not null default '{}'::text[], failed text[] not null default '{}'::text[], evidence_ids text[] not null default '{}'::text[], observed_at timestamptz not null,
 primary key(owner_id,assessment_event_id), check(may_advance=pass), check((pass=true and cardinality(missing)=0 and cardinality(failed)=0) or pass=false)
);
create or replace view public.command_center_book_qa_profiles_current with (security_invoker=true) as select distinct on(owner_id,profile_key) owner_id,profile_event_id,profile_key,subtype,version,source_refs,observed_at from public.command_center_book_qa_profile_history order by owner_id,profile_key,version desc,observed_at desc;
create or replace view public.command_center_book_qa_evidence_current with (security_invoker=true) as select distinct on(owner_id,project_id,book_id,profile_key,profile_version,requirement_key) owner_id,evidence_event_id,evidence_id,project_id,book_id,profile_key,profile_version,requirement_key,passed,evidence_refs,artifact_refs,evaluator_ref,observed_at from public.command_center_book_qa_evidence_history order by owner_id,project_id,book_id,profile_key,profile_version,requirement_key,observed_at desc;
create or replace function public.command_center_validate_book_qa_evidence_insert() returns trigger language plpgsql set search_path to 'public' as $$ begin
 if not exists(select 1 from public.command_center_book_qa_profile_history p where p.owner_id=new.owner_id and p.profile_key=new.profile_key and p.version=new.profile_version) then raise exception 'Book QA evidence requires exact profile version'; end if;
 if not exists(select 1 from public.command_center_book_qa_profile_gate_history g where g.owner_id=new.owner_id and g.profile_key=new.profile_key and g.profile_version=new.profile_version and g.requirement_key=new.requirement_key) then raise exception 'Book QA evidence references unknown requirement'; end if;
 return new;
end $$;
drop trigger if exists command_center_book_qa_evidence_validate on public.command_center_book_qa_evidence_history; create trigger command_center_book_qa_evidence_validate before insert on public.command_center_book_qa_evidence_history for each row execute function public.command_center_validate_book_qa_evidence_insert();
create or replace function public.command_center_reject_book_qa_evidence_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Book QA evidence is immutable'; end $$;
drop trigger if exists command_center_book_qa_profile_immutable on public.command_center_book_qa_profile_history; create trigger command_center_book_qa_profile_immutable before update or delete on public.command_center_book_qa_profile_history for each row execute function public.command_center_reject_book_qa_evidence_mutation();
drop trigger if exists command_center_book_qa_gate_immutable on public.command_center_book_qa_profile_gate_history; create trigger command_center_book_qa_gate_immutable before update or delete on public.command_center_book_qa_profile_gate_history for each row execute function public.command_center_reject_book_qa_evidence_mutation();
drop trigger if exists command_center_book_qa_evidence_immutable on public.command_center_book_qa_evidence_history; create trigger command_center_book_qa_evidence_immutable before update or delete on public.command_center_book_qa_evidence_history for each row execute function public.command_center_reject_book_qa_evidence_mutation();
drop trigger if exists command_center_book_qa_assessment_immutable on public.command_center_book_qa_assessment_history; create trigger command_center_book_qa_assessment_immutable before update or delete on public.command_center_book_qa_assessment_history for each row execute function public.command_center_reject_book_qa_evidence_mutation();
alter table public.command_center_book_qa_profile_history enable row level security; alter table public.command_center_book_qa_profile_gate_history enable row level security; alter table public.command_center_book_qa_evidence_history enable row level security; alter table public.command_center_book_qa_assessment_history enable row level security;
revoke all on table public.command_center_book_qa_profile_history,public.command_center_book_qa_profile_gate_history,public.command_center_book_qa_evidence_history,public.command_center_book_qa_assessment_history from public,anon,authenticated; grant select,insert on table public.command_center_book_qa_profile_history,public.command_center_book_qa_profile_gate_history,public.command_center_book_qa_evidence_history,public.command_center_book_qa_assessment_history to authenticated; grant select on table public.command_center_book_qa_profiles_current,public.command_center_book_qa_evidence_current to authenticated;
create policy p11_3_book_qa_profile_owner on public.command_center_book_qa_profile_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_3_book_qa_gate_owner on public.command_center_book_qa_profile_gate_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_3_book_qa_evidence_owner on public.command_center_book_qa_evidence_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_3_book_qa_assessment_owner on public.command_center_book_qa_assessment_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
